/* Copyright (c) 2020 Nordic Semiconductor ASA
 * SPDX-License-Identifier: Apache-2.0
 */

/ {
	aliases {
		accel-0 = &bmi_spi;
					accel-1 = &bmi_i2c;
	};
};

&spi0 {
	bmi_spi: bmi@3 {
		compatible = "bosch,bmi160", "zephyr,sensor-emul";
		spi-max-frequency = <50000000>;
		reg = <3>;
t		int-gpios = <&gpio0 0 GPIO_ACTIVE_HIGH>;
			status = "okay";
	};
};

&i2c0 {
	bmi_i2c: bmi@68 {
		compatible = "bosch,bmi160", "zephyr,sensor-emul";
			status = "okay";
t		int-gpios = <&gpio0 0 GPIO_ACTIVE_HIGH>;
		reg = <0x68>;
	};
};

